class Solution {
public:
    int fib(int n) {
        int last = 1;
        int slast = 0;
        int cur;
        for(int i = 2; i<=n; i++){
            cur = last+slast;
            slast = last;
            last = cur;
        }
        return cur;
    }
};
```

